struct ScopedDescriptorProductDeviceAllocationReuse {
    bool previous = false;
    bool owns_scope = false;

    explicit ScopedDescriptorProductDeviceAllocationReuse(bool enabled)
        : previous(g_descriptor_product_reuse_device_allocations) {
        if (enabled && !previous) {
            release_descriptor_device_allocation_pool();
            reset_descriptor_device_allocation_pool_stats();
            g_descriptor_product_reuse_device_allocations = true;
            owns_scope = true;
        }
    }

    ~ScopedDescriptorProductDeviceAllocationReuse() {
        if (owns_scope) {
            const DescriptorDeviceAllocationPoolStats stats =
                g_descriptor_device_allocation_pool_stats;
            const uint64_t cached_bytes =
                descriptor_device_allocation_pool_cached_bytes();
            uint64_t in_use_blocks = UINT64_C(0);
            uint64_t in_use_bytes = UINT64_C(0);
            for (const DescriptorDeviceAllocationPoolBlock &block :
                 g_descriptor_device_allocation_pool) {
                if (block.in_use) {
                    ++in_use_blocks;
                    in_use_bytes += static_cast<uint64_t>(block.bytes);
                }
            }
            const uint64_t release_start_ns = qrt_now_ns();
            release_descriptor_device_allocation_pool();
            const double release_ms = static_cast<double>(
                qrt_elapsed_ns(release_start_ns, qrt_now_ns())
            ) / 1000000.0;
            std::cerr << "BATCH_MARK device_allocation_pool requests="
                      << stats.request_count
                      << " reuse=" << stats.reuse_count
                      << " new=" << stats.new_allocation_count
                      << " release=" << stats.release_count
                      << " cached_bytes=" << cached_bytes
                      << " peak_cached_bytes=" << stats.peak_cached_bytes
                      << " in_use_blocks=" << in_use_blocks
                      << " in_use_bytes=" << in_use_bytes
                      << " release_ms=" << release_ms
                      << std::endl;
        }
        g_descriptor_product_reuse_device_allocations = previous;
    }
}

